  vocab=[("sustitución", "reemplazar una incógnita por su expresión"), ("igualación", "igualar dos expresiones de la misma incógnita"), ("reducción", "sumar o restar ecuaciones para eliminar una incógnita"), ("despejar", "dejar una incógnita sola en un lado"), ("eliminar una incógnita", "hacer desaparecer una letra al sumar o restar")],
